<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?></title><link rel="stylesheet" href="<?= e(site_url('themes/newspress/assets/style.css')) ?>"></head><body><div class="top">THE DAILY EDITION</div><header class="wrap masthead"><a href="<?= e(site_url()) ?>">PAPER CAST</a></header><nav><div class="wrap"><a href="<?= e(site_url()) ?>">HOME</a><a href="<?= e(site_url('about.php')) ?>">ABOUT</a><a href="<?= e(site_url('search.php')) ?>">SEARCH</a></div></nav><main class="wrap article"><?php if($post): ?><small><?= e($post['category_name']??'NEWS') ?></small><h1><?= e($post['title']) ?></h1><?php if($post['cover_image']): ?><img class="hero-image" src="<?= e($post['cover_image']) ?>" alt=""><?php endif ?><div class="body"><?= nl2br(e($post['content'])) ?></div><form method="post" action="<?= e(site_url('like.php')) ?>"><input type="hidden" name="_token" value="<?= e($_SESSION['csrf_token']) ?>"><input type="hidden" name="post_id" value="<?= (int)$post['id'] ?>"><input type="hidden" name="slug" value="<?= e($post['slug']) ?>"><button><?= $liked?'♥ Liked':'♡ Like' ?> · <?= (int)$likeCount ?></button></form><section id="comments"><h2>Comments</h2><?php foreach($comments as $comment): ?><p><strong><?= e($comment['name']) ?></strong>: <?= e($comment['body']) ?></p><?php endforeach ?><form method="post" action="<?= e(site_url('comment.php')) ?>"><input type="hidden" name="_token" value="<?= e($_SESSION['csrf_token']) ?>"><input type="hidden" name="post_id" value="<?= (int)$post['id'] ?>"><input type="hidden" name="slug" value="<?= e($post['slug']) ?>"><input name="name" placeholder="Name" required><input name="email" type="email" placeholder="Email" required><textarea name="body" placeholder="Your comment" required></textarea><button>Submit for review</button></form></section><?php else: ?><h1>Story not found</h1><?php endif ?></main></body></html>